from class12_chemistry_opening import pair,section,SOURCE
from class12_chemistry_sync import save
from class12_chemistry_rings import Fig
import math
F=Fig('arrow151');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def lines(rows,kind='list'):
 s0=len(paras)
 for r in rows:paras.append(pair(*r))
 layout.append({'type':kind,'indices':list(range(s0,len(paras)))})
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
N={'prurine':('پیورین','پیورین'),'pyrimidine':('پیریمیڈین','پیریمیډین')}
def lb(lang,v):return v if lang=='en' else N[v][0 if lang=='ur' else 1]
def atom(x,y,v,size=14):return f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{6+4*len(v)}" fill="#fff"/>'+t(x,y+5,v,size)
def bases(lang):
 s=F.start(170);cx,cy,r=300,90,36
 P=[(cx+r*math.sin(math.radians(60*i)),cy-r*math.cos(math.radians(60*i))) for i in range(6)]
 Q=[P[1],(P[1][0]+34,P[1][1]-12),(P[1][0]+54,cy),(P[2][0]+34,P[2][1]+12),P[2]]
 for i in range(6):s+=line(*P[i],*P[(i+1)%6],2)
 for i in range(4):s+=line(*Q[i],*Q[i+1],2)
 for a,b in ((5,0),(3,4)):
  (x1,y1),(x2,y2)=P[a],P[b];s+=line(x1+(cx-x1)*.18,y1+(cy-y1)*.18,x2+(cx-x2)*.18,y2+(cy-y2)*.18,2)
 s+=line(P[1][0]-4,P[1][1]+6,P[2][0]-4,P[2][1]-6,2)+line(Q[1][0]+3,Q[1][1]+6,Q[2][0]-4,Q[2][1]-4,2)
 s+=atom(*P[5],'N')+atom(*P[4],'HC')+atom(*P[3],'N')+atom(*P[0],'C')+line(P[0][0],P[0][1]-8,P[0][0],P[0][1]-20)+t(P[0][0],P[0][1]-24,'H',13)+atom(*P[1],'C')+atom(*P[2],'C')
 s+=atom(*Q[1],'N')+atom(*Q[2],'CH')+atom(*Q[3],'N')+line(Q[3][0],Q[3][1]+8,Q[3][0],Q[3][1]+20)+t(Q[3][0],Q[3][1]+34,'H',13)+t(cx+10,165,lb(lang,'prurine'),12)
 cx2=600;P=[(cx2+r*math.sin(math.radians(60*i)),cy-r*math.cos(math.radians(60*i))) for i in range(6)]
 for i in range(6):s+=line(*P[i],*P[(i+1)%6],2)
 for a,b in ((0,1),(2,3),(4,5)):
  (x1,y1),(x2,y2)=P[a],P[b];s+=line(x1+(cx2-x1)*.18,y1+(cy-y1)*.18,x2+(cx2-x2)*.18,y2+(cy-y2)*.18,2)
 s+=atom(*P[5],'N')+atom(*P[3],'N')+t(cx2,165,lb(lang,'pyrimidine'),12)
 return s+'</svg>'

add('… the resulting high levels of glucose in the blood and the inadequate amount of glucose in the cells together produce the symptoms and complications of diabetes. Diabetes mellitus is a disorder in which the amount of sugar in the blood is elevated. Doctors often use the full name diabetes mellitus, rather than diabetes alone, to distinguish this disorder from diabetes insipidus.','… تو خون میں گلوکوز کی زیادہ سطح اور خلیوں میں گلوکوز کی ناکافی مقدار مل کر ذیابیطس کی علامات اور پیچیدگیاں پیدا کرتی ہیں۔ ذیابیطس میلیٹس ایک عارضہ ہے جس میں خون میں شکر کی مقدار بڑھ جاتی ہے۔ ڈاکٹر اس عارضے کو ذیابیطس انسپیڈس سے ممتاز کرنے کے لیے اکثر صرف ذیابیطس کے بجائے پورا نام ذیابیطس میلیٹس استعمال کرتے ہیں۔','… نو په وینه کې د ګلوکوز لوړه کچه او په حجرو کې د ګلوکوز ناکافي اندازه یو ځای د شکرې نښې او اختلاطات رامنځته کوي. ډایابېټیز میلیټس یو اختلال دی چې پکې په وینه کې د بورې اندازه لوړېږي. ډاکټران ډېری د یوازې ډایابېټیز پر ځای بشپړ نوم ډایابېټیز میلیټس کاروي څو دا اختلال له ډایابېټیز انسیپیډس څخه جلا کړي.')
lines([('Diabetes mellitus is a disorder in which blood sugar (glucose) levels are abnormally high because the body does not produce enough insulin to meet its needs.','ذیابیطس میلیٹس ایک عارضہ ہے جس میں خون میں شکر (گلوکوز) کی سطح غیر معمولی طور پر زیادہ ہوتی ہے کیونکہ جسم اپنی ضرورت کے مطابق کافی انسولین نہیں بناتا۔','ډایابېټیز میلیټس یو اختلال دی چې پکې د وینې د بورې (ګلوکوز) کچه په غیر عادي ډول لوړه وي ځکه بدن د خپلې اړتیا سره سم کافي انسولین نه تولیدوي.'),
 ('Diabetes insipidus is a relatively rare disorder that does not affect blood glucose levels but, just like diabetes mellitus, also causes increased urination.','ذیابیطس انسپیڈس نسبتاً نایاب عارضہ ہے جو خون میں گلوکوز کی سطح کو متاثر نہیں کرتا لیکن ذیابیطس میلیٹس کی طرح پیشاب کی زیادتی کا باعث بنتا ہے۔','ډایابېټیز انسیپیډس نسبتاً نادر اختلال دی چې د وینې د ګلوکوز پر کچه اغېز نه کوي خو د ډایابېټیز میلیټس په څېر د زیاتو متیازو لامل کېږي.')])
add('21.4.4 Nutritional and Biological Importance of lipids','21.4.4 لپڈز کی غذائی اور حیاتیاتی اہمیت','21.4.4 د لیپیډونو غذايي او بیولوژیکي اهمیت','heading')
add('Lipids perform a number of different functions in living organisms. Some of these are listed below.','لپڈز جانداروں میں کئی مختلف افعال انجام دیتے ہیں۔ ان میں سے چند نیچے درج ہیں۔','لیپیډونه په ژوندیو موجوداتو کې یو شمېر بېلابېلې دندې ترسره کوي. ځینې یې لاندې لیکل شوې.')
lines([('Lipids provide food, which is highly rich in calorific value. One gram of lipid on complete oxidation produces 9.3 kcal of heat, which is about double the amount produced by carbohydrates and proteins.','لپڈز ایسی خوراک مہیا کرتے ہیں جو حرارتی قدر میں بہت بھرپور ہے۔ ایک گرام لپڈ کی مکمل تکسید سے 9.3 kcal حرارت پیدا ہوتی ہے، جو کاربوہائیڈریٹس اور پروٹینز سے پیدا ہونے والی مقدار کا تقریباً دوگنا ہے۔','لیپیډونه داسې خواړه برابروي چې په کالوري ارزښت کې ډېر بډای دي. د یوه ګرام لیپیډ بشپړ اکسیډېشن 9.3 kcal تودوخه تولیدوي، چې د کاربوهایدرېټونو او پروټینونو له تولید شوې اندازې نږدې دوه چنده ده.'),
 ('Lipids are insoluble in water and, therefore, they can be stored easily in the body as food reserves. The organisms then use these food reserves during hibernation periods.','لپڈز پانی میں ناحل پذیر ہیں اس لیے انہیں جسم میں خوراک کے ذخیرے کے طور پر آسانی سے محفوظ کیا جا سکتا ہے۔ پھر جاندار سرمائی نیند کے دوران یہ ذخیرے استعمال کرتے ہیں۔','لیپیډونه په اوبو کې نه حلېږي، نو په بدن کې د خوړو د زېرمو په توګه په اسانۍ ساتل کېدای شي. بیا ژوندي موجودات د ژمني خوب پر مهال دا زېرمې کاروي.'),
 ('Lipids in association with different proteins form the important constituents of cell membranes.','لپڈز مختلف پروٹینز کے ساتھ مل کر خلوی جھلیوں کے اہم اجزا بناتے ہیں۔','لیپیډونه له بېلابېلو پروټینونو سره یو ځای د حجروي غشاوو مهمې برخې جوړوي.'),
 ('Fats have high insulating capacity. Great quantities of fats are deposited in the sub-cutaneous layers in aquatic mammals such as whale and in animals of cold climates. These fat deposits protect these animals from severe cold and severe temperature changes.','چکنائیوں کی حاجز صلاحیت زیادہ ہے۔ وہیل جیسے آبی ممالیہ اور سرد علاقوں کے جانوروں میں جلد کے نیچے کی تہوں میں چکنائی کی بڑی مقدار جمع ہوتی ہے۔ چکنائی کے یہ ذخیرے ان جانوروں کو شدید سردی اور درجہ حرارت کی شدید تبدیلیوں سے بچاتے ہیں۔','غوړي لوړ عایق ظرفیت لري. په اوبو کې تي لرونکو لکه وېل او د سړو سیمو په ژویو کې د پوستکي لاندې په پوړونو کې د غوړیو لوی مقدار راټولېږي. د غوړیو دا زېرمې دا ژوي له سختې یخنۍ او د تودوخې له سختو بدلونونو ساتي.'),
 ('Some lipids especially phospholipids play a key role in the absorption and transportation of fatty acids in the body.','بعض لپڈز خاص طور پر فاسفو لپڈز جسم میں فیٹی ایسڈز کے جذب اور نقل و حمل میں کلیدی کردار ادا کرتے ہیں۔','ځینې لیپیډونه په ځانګړي ډول فاسفو لیپیډونه په بدن کې د غوړ اسیدونو په جذب او لېږد کې کلیدي رول لوبوي.'),
 ('Sex hormones, adrenocorticoids, cholic acids are synthesized from a steroidal lipid known as cholesterol.','جنسی ہارمونز، ایڈرینو کورٹیکوئڈز اور کولک ایسڈز کولیسٹرول نامی سٹیرائیڈی لپڈ سے تالیف ہوتے ہیں۔','جنسي هورمونونه، اډرینو کورټیکوایډونه او کولیک اسیدونه له یوه سټېرایډي لیپیډ څخه جوړېږي چې کولیسټرول بلل کېږي.'),
 ('Lipids serve as carrier of fats soluble vitamins such as vitamin A, D and E in the body.','لپڈز جسم میں چکنائی میں حل پذیر وٹامنز جیسے وٹامن A، D اور E کے حامل کے طور پر کام کرتے ہیں۔','لیپیډونه په بدن کې په غوړیو کې د حلېدونکو ویټامینونو لکه ویټامین A، D او E د وړونکو په توګه کار کوي.'),
 ('Squealing, a steroid present in the blood of shark has antibiotic and antifungal properties. This explains why sharks rarely contract infections and almost never get cancer.','سکوالین، شارک کے خون میں موجود ایک سٹیرائیڈ، اینٹی بائیوٹک اور پھپھوندی کش خصوصیات رکھتا ہے۔ اس سے وضاحت ہوتی ہے کہ شارک کو انفیکشن کم ہی ہوتا ہے اور کینسر تقریباً کبھی نہیں ہوتا۔','سکوالین، د شارک په وینه کې شته یو سټېرایډ، انټي بیوټیک او ضد پوڅکي ځانګړنې لري. دا روښانه کوي چې ولې شارکونه ډېر لږ په انتاناتو اخته کېږي او نږدې هېڅکله سرطان نه اخلي.')])
add('21.5 Nucleic Acids','21.5 نیوکلک ایسڈز','21.5 نیوکلیک اسیدونه','heading')
add('Nucleic acids are macromolecules that allow organisms to transfer genetic information from one generation to the next. They are present in every living organism as well as viruses. They have been found to be the essential substance of the genes and the apparatus by which the genes act or express themselves. They contain in their structure the blueprints for the normal growth and development of each and every organism','نیوکلک ایسڈز وہ بڑے سالمات ہیں جو جانداروں کو جینیاتی معلومات ایک نسل سے اگلی نسل میں منتقل کرنے کے قابل بناتے ہیں۔ یہ ہر جاندار اور وائرسوں میں موجود ہیں۔ یہ جینز کا بنیادی مادہ اور وہ آلہ پائے گئے ہیں جس سے جینز عمل کرتے یا خود کو ظاہر کرتے ہیں۔ ان کی ساخت میں ہر جاندار کی معمول کی نشوونما اور ترقی کے خاکے ہوتے ہیں','نیوکلیک اسیدونه هغه لوی مالیکولونه دي چې ژوندیو موجوداتو ته اجازه ورکوي جنیټیکي معلومات له یوه نسل څخه بل ته ولېږدوي. په هر ژوندي موجود او ویروسونو کې شته. موندل شوي چې د جینونو اساسي ماده او هغه وسیله ده چې جینونه پرې عمل کوي یا ځان څرګندوي. په خپل جوړښت کې د هر ژوندي موجود د عادي ودې او پرمختګ نقشې لري')
lines([('Nucleic acids are the main information-carrying molecules of the cell, and, by directing the process of protein synthesis, they determine the inherited characteristics of every living thing.','نیوکلک ایسڈز خلیے کے معلومات لے جانے والے اہم سالمات ہیں، اور پروٹین کی تالیف کے عمل کی رہنمائی کر کے یہ ہر جاندار کی موروثی خصوصیات متعین کرتے ہیں۔','نیوکلیک اسیدونه د حجرې اصلي معلومات وړونکي مالیکولونه دي، او د پروټین د جوړېدو د عملیې په لارښوونه سره د هر ژوندي شي میراثي ځانګړنې ټاکي.'),
 ('The two main classes of nucleic acids are deoxyribonucleic acid (DNA) and ribonucleic acid (RNA).','نیوکلک ایسڈز کی دو بڑی جماعتیں ڈی آکسی رائبونیوکلک ایسڈ (DNA) اور رائبونیوکلک ایسڈ (RNA) ہیں۔','د نیوکلیک اسیدونو دوه اصلي ډلې ډی اکسي رایبونیوکلیک اسید (DNA) او رایبونیوکلیک اسید (RNA) دي.'),
 ('DNA is the genetic material found in living organisms, from single-celled bacteria to multicellular mammals.','DNA وہ جینیاتی مادہ ہے جو یک خلوی بیکٹیریا سے کثیر خلوی ممالیہ تک جانداروں میں پایا جاتا ہے۔','DNA هغه جنیټیکي ماده ده چې له یو حجروي باکتریاوو تر څو حجروي تي لرونکو پورې په ژوندیو موجوداتو کې موندل کېږي.'),
 ('RNA is the genetic material of certain viruses, but it is also found in all living cells, where it plays an important role in certain processes such as the synthesis of proteins.','RNA بعض وائرسوں کا جینیاتی مادہ ہے، لیکن یہ تمام زندہ خلیوں میں بھی پایا جاتا ہے جہاں یہ پروٹینز کی تالیف جیسے بعض عمل میں اہم کردار ادا کرتا ہے۔','RNA د ځینو ویروسونو جنیټیکي ماده ده، خو په ټولو ژوندیو حجرو کې هم موندل کېږي چې پکې په ځینو عملیو لکه د پروټینونو په جوړولو کې مهم رول لوبوي.'),
 ('They are capable of being broken down to yield phosphoric acid, sugars, and a mixture of organic bases (purines and pyrimidines).','انہیں توڑ کر فاسفورک ایسڈ، شکر اور نامیاتی اساسوں (پیورینز اور پیریمیڈینز) کا آمیزہ حاصل کیا جا سکتا ہے۔','دوی د ماتېدو وړ دي او فاسفوریک اسید، بورې او د عضوي قلویاتو (پیورینونو او پیریمیډینونو) ګډوله ورکوي.')])
add('Nucleic acids are substances present in the nuclei of cells which are involved in the storage, expressing, transmission and processing of genetic information and mutation in living organisms. The monomer that makes up a nucleic acid is called a nucleotide.','نیوکلک ایسڈز خلیوں کے مرکزوں میں موجود وہ مادے ہیں جو جانداروں میں جینیاتی معلومات کے ذخیرے، اظہار، منتقلی اور عمل کاری اور تغیر میں شامل ہیں۔ نیوکلک ایسڈ بنانے والے مونومر کو نیوکلیوٹائیڈ کہتے ہیں۔','نیوکلیک اسیدونه د حجرو په هستو کې شته هغه مواد دي چې په ژوندیو موجوداتو کې د جنیټیکي معلوماتو په زېرمه کولو، څرګندولو، لېږد او پروسس او بدلون (میوټېشن) کې ونډه لري. هغه مونومر چې نیوکلیک اسید جوړوي نیوکلیوټایډ بلل کېږي.')
add('Types of Nucleic Acids','نیوکلک ایسڈز کی اقسام','د نیوکلیک اسیدونو ډولونه','heading')
add('There are two types of nucleic acids.','نیوکلک ایسڈز کی دو اقسام ہیں۔','د نیوکلیک اسیدونو دوه ډولونه شته.')
lines([('DNA (Deoxyribonucleic acid) it is present in nuclei and in some viruses. It is the main constituent of chromosome.','DNA (ڈی آکسی رائبونیوکلک ایسڈ) مرکزوں اور بعض وائرسوں میں موجود ہے۔ یہ کروموسوم کا بنیادی جزو ہے۔','DNA (ډی اکسي رایبونیوکلیک اسید) په هستو او ځینو ویروسونو کې شته. دا د کروموزوم اصلي برخه ده.'),
 ('RNA (Ribonucleic acid) is present in the cytoplasm and in some viruses.','RNA (رائبونیوکلک ایسڈ) سائٹوپلازم اور بعض وائرسوں میں موجود ہے۔','RNA (رایبونیوکلیک اسید) په سایټوپلازم او ځینو ویروسونو کې شته.')])
add('21.5.1 Structural Components of DNA and RNA','21.5.1 DNA اور RNA کے ساختی اجزا','21.5.1 د DNA او RNA جوړښتي برخې','heading')
add('Watson and Crick determined the structure of nucleic acids. Both DNA and RNA are formed by the polymerization of large number of units known as nucleotides. That is why DNA and RNA are polynucleotides. A nucleotide is composed of a nitrogenous base, a sugar and a phosphate group. DNA differs from RNA in the type of nitrogenous base and type of sugar unit. The nitrogenous bases are of two types, purine and pyrimidine.','واٹسن اور کرک نے نیوکلک ایسڈز کی ساخت متعین کی۔ DNA اور RNA دونوں نیوکلیوٹائیڈز کہلانے والی بڑی تعداد میں اکائیوں کی پولیمرائزیشن سے بنتے ہیں۔ اسی لیے DNA اور RNA پولی نیوکلیوٹائیڈز ہیں۔ نیوکلیوٹائیڈ ایک نائٹروجنی اساس، ایک شکر اور ایک فاسفیٹ گروپ پر مشتمل ہے۔ DNA نائٹروجنی اساس کی قسم اور شکر کی اکائی کی قسم میں RNA سے مختلف ہے۔ نائٹروجنی اساس دو قسم کے ہیں، پیورین اور پیریمیڈین۔','واټسن او کریک د نیوکلیک اسیدونو جوړښت وټاکه. DNA او RNA دواړه د نیوکلیوټایډونو په نوم د ډېرو واحدونو د پولیمرایزېشن په واسطه جوړېږي. له همدې امله DNA او RNA پولي نیوکلیوټایډونه دي. یو نیوکلیوټایډ له یوې نایټروجني قلوي، یوې بورې او یوه فاسفېټ ګروپ څخه جوړ دی. DNA د نایټروجني قلوي د ډول او د بورې د واحد د ډول له مخې له RNA توپیر لري. نایټروجني قلوي دوه ډوله دي، پیورین او پیریمیډین.')
